from datetime import datetime, timedelta
import functools

class TokenBucket:
    def __init__(self, rate, capacity, clock):
        if not isinstance(rate, (int, float)) or rate <= 0:
            raise ValueError("Rate must be a positive number")
        if not isinstance(capacity, (int, float)) or capacity <= 0:
            raise ValueError("Capacity must be a positive number")
        self._rate = rate
        self._capacity = capacity
        self._time = clock()
        self._time_refill = 0.0  # initial time for refill

    def _update(self, time):
        self._time = time
        self._time_refill = max(self._time_refill, time)

    def refill(self):
        self._update(self._time)
        self._time_refill = self._time

    def _get_time(self):
        return self._time

    def _get_refill_time(self):
        return self._time_refill

    def _add_tokens(self, time):
        delta = time - self._time
        if delta <= 0:
            return 0.0
        self._time = time
        return self._rate * delta

    @property
    def available(self):
        return self._capacity - self._add_tokens(self._time_refill)

    def try_acquire(self, n):
        time_refill = self._get_refill_time()
        available = self.available
        if available >= n:
            self._add_tokens(self._get_time())
            return True
        if available < n:
            return False
        self._add_tokens(self._get_time())
        return False

    def wait_time(self, n):
        time_refill = self._get_refill_time()
        available = self.available
        if available >= n:
            return 0.0
        if available < n:
            return 0.0
        self._add_tokens(self._get_time())
        return 0.0

    def __repr__(self):
        return f"TokenBucket(rate={self._rate}, capacity={self._capacity}, clock={self._time})"
